    data?.let{(binding,items)->Card(modifier.fillMaxWidth().testTag("dispatched-visit")){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Dispatched · generation ${binding.appliedGeneration}",style=MaterialTheme.typography.titleMedium);binding.managerReference?.let{Text("Job $it")};binding.instructionsSnapshot?.let{Text("Dispatch instructions\n$it",Modifier.testTag("dispatch-instructions"))};if(detail.state=="PARTICIPATION_COMPLETE")Text("Participation complete. This records only your local involvement; it does not mean the central job was cancelled, accepted, or reported.");if(detail.state=="DISPATCH_WITHDRAWN")Text("Dispatch assignment withdrawn by a newer generation. This is not a central cancellation.");items.forEach{i->Text("${i.taskNameSnapshot}\n${if(i.assignmentMeaning=="EVERYONE")"Assigned to everyone" else "Assigned technicians preserved"} · ${i.localRole.replace('_',' ').lowercase()} · ${i.documentationDisposition.replace('_',' ').lowercase()}");if(detail.state=="WORKING"){if(i.documentationDisposition in setOf("PENDING","LEADER_OBSERVE"))Button({scope.launch{message=withContext(Dispatchers.IO){svc.documentLocally(detail.id,i.dispatchItemId)};reload()}},Modifier.fillMaxWidth()){Text("Document this item")};if(i.localRole=="ASSIGNED"&&i.documentationDisposition!="DEFERRED"){OutlinedButton({scope.launch{runCatching{withContext(Dispatchers.IO){svc.handoffReview(detail.id,i.dispatchItemId)}}.onSuccess{r->handoffItem=i;review=r}.onFailure{message=it.message}}},Modifier.fillMaxWidth().testTag("handoff-open-${i.dispatchItemId}")){Text("Hand off documentation…")}};if(i.documentationDisposition=="DEFERRED")OutlinedButton({scope.launch{withContext(Dispatchers.IO){svc.undoHandoff(detail.id,i.dispatchItemId)};reload()}},Modifier.fillMaxWidth()){Text("Document this item myself")}}};if(detail.state=="WORKING"&&items.filter{it.localRole=="ASSIGNED"}.all{it.documentationDisposition=="DEFERRED"}&&items.none{it.documentationDisposition=="